import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, notification, Input, Button, Alert, Checkbox } from 'antd'
import _ from 'lodash/object'
import { isEmpty } from 'lodash/lang'
import {
  ContainerStyle, GosureFormContainer, ContainerTitle, ContainerSubTitle,
  ContainerGroupStyle, AddressTitleStyle, ButtonContainer
} from './index.style'
import IntlMessages from '../../../../../components/utility/intlMessages'
import { ENDORSE_LANG } from '../../../constants'
import { LANG_STRINGS, ERROR_STRINGS } from '../../../../../constants/lang'
import policyAction from '../../../../../redux/policy/actions'
import endoseActions from '../../../../../redux/Endorsement/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import FileUploadSection from '../FileUploadSection'
import EndorseWelcome from '../EndorseWelcome'
import { returnNewObjectOnlyValidKeys } from '../../../../../helpers/utility'

const { getPolicyDetails, getAggregatePolicyDetails } = policyAction
const { submitGosureEndorseForm, resetGosureEndorseRedux, submitAggregateEndorse } = endoseActions

class GosureEndorseContainer extends Component {
  static propTypes = {
    id: PropTypes.string,
    aggregateId: PropTypes.string,
    productId: PropTypes.string
  }

  constructor (props) {
    super(props)
    this.state = {
      isBtnDisAbled: true,
      isCheckBoxChecked: true
    }
    this.textareaValue = {}
    this.imageUrls = {}
    this.isAllImages = false
    this.firstInternalId = ''
    this.totalPolicies = 0
  }

  componentDidMount () {
    const {
      id, aggregateId, productId, getPolicyDetails,
      getAggregatePolicyDetails
    } = this.props
    if (id) {
      getPolicyDetails(id)
    } else {
      // this is used to get aggregate details
      getAggregatePolicyDetails({
        aggregation_id: aggregateId,
        product: productId
      })
    }
  }

  componentWillReceiveProps (nextProps) {
    const { submitGosureError, gosureDetailsMessage } = nextProps
    if (submitGosureError && gosureDetailsMessage && (gosureDetailsMessage !== 'success')) {
      notification['error']({
        message: this.intlText({ id: 'Error' }),
        description: submitGosureError && gosureDetailsMessage
          ? this.intlText({ id: gosureDetailsMessage }) : ''
      })
      // this is clear the error messsage if any left after popup show
      this.props.resetGosureEndorseRedux(['gosureDetailsMessage'])
    }
  }

  isTotalFieldEqPolicies = (obj) => {
    return Object.keys(obj).length === this.totalPolicies
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  onChangeCheckBox = (e) => {
    this.setState({
      isCheckBoxChecked: e.target.checked
    }, () => {
      this.checkAddressForAll()
    })
  }

  checkAddressForAll = () => {
    const { isCheckBoxChecked } = this.state
    if (isCheckBoxChecked) {
      const text = this.textareaValue[this.firstInternalId]
      this.setState({
        isBtnDisAbled: !(this.isAllImages && text)
      })
      this.textareaValue = returnNewObjectOnlyValidKeys(this.textareaValue, [this.firstInternalId])
    } else {
      const isAllAddress = this.isTotalFieldEqPolicies(this.textareaValue)
      this.setState({
        isBtnDisAbled: !(this.isAllImages && isAllAddress)
      })
    }
  }

  onChangeAddress = (e, internalId) => {
    const { isCheckBoxChecked } = this.state
    const addressText = e.target.value
    if (addressText) {
      this.textareaValue[internalId] = addressText && addressText.trim()
    } else {
      delete this.textareaValue[internalId]
    }
    if (isCheckBoxChecked) {
      const text = this.textareaValue[internalId]
      this.setState({
        isBtnDisAbled: !(this.isAllImages && text)
      })
    } else {
      this.checkAddressForAll()
    }
  }

  getUploadUrls = (data, isAllImages, internalId) => {
    this.imageUrls[internalId] = data
    this.isAllImages = isAllImages && this.isTotalFieldEqPolicies(this.imageUrls)
    if (isAllImages) {
      this.checkAddressForAll()
    }
  }

  submitGosureEndorseForm = () => {
    if (_.get(this.props, 'aggregateId', '')) {
      this.submitAggregateForm()
    } else {
      const internalId = _.get(this.props, 'detailsData.InternalID', '')
      const body = this.getReqPhotoAndAddress(internalId)
      this.props.submitGosureEndorseForm({ body, id: _.get(this.props, 'detailsData.InternalID', '') })
    }
  }

  getReqPhotoAndAddress = (keys) => {
    return {
      photo: {
        top: _.get(this, `imageUrls[${keys}].top`),
        left: _.get(this, `imageUrls[${keys}].left`),
        right: _.get(this, `imageUrls[${keys}].right`),
        bottom: _.get(this, `imageUrls[${keys}].bottom`)
      },
      address: this.state.isCheckBoxChecked ? this.textareaValue[Object.keys(this.textareaValue)[0]]
        : this.textareaValue[keys]
    }
  }

  submitAggregateForm = () => {
    // this is called for aggregate time...
    // this is the request body in case of aggregate flow
    const reqBody = []
    for (const keys in this.imageUrls) {
      const obj = {
        internal_id: keys,
        detail: this.getReqPhotoAndAddress(keys)
      }
      reqBody.push(obj)
    }
    this.props.submitAggregateEndorse({ body: reqBody, id: _.get(this.props, 'productId', '') })
  }

  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }

  getEndorseForms = (policyData) => {
    const { isCheckBoxChecked } = this.state
    const { aggregateDetailsData } = this.props
    const formData = []
    policyData.forEach((data, index) => {
      if (_.get(data, 'EndorsementStatus', '') !== 'SUCCESS') {
        formData.push(
          <React.Fragment>
            <ContainerGroupStyle>
              <IntlMessages id={_.get(data, 'Request.item', '')} />
            </ContainerGroupStyle>
            <ContainerSubTitle>
              <IntlMessages id={ENDORSE_LANG.groupSubTitle} />
            </ContainerSubTitle>
            <FileUploadSection
              internalId={_.get(data, 'InternalID', '')}
              getUploadUrls={this.getUploadUrls}
            />
            {
              (!isCheckBoxChecked || index < 1) && (
                <div>
                  <Row type='flex' justify='space-between' className='address-textarea'>
                    <Col>
                      <AddressTitleStyle>
                        <IntlMessages id={ENDORSE_LANG.enterAddress} />
                      </AddressTitleStyle>
                    </Col>
                    {
                      (aggregateDetailsData.length > 1 && index < 1) && (
                        <Col>
                          <Checkbox
                            checked={isCheckBoxChecked}
                            onChange={this.onChangeCheckBox}
                          >
                            {ENDORSE_LANG.sameAddressForAll}
                          </Checkbox>
                        </Col>
                      )
                    }
                  </Row>
                  <Input.TextArea
                    rows={4}
                    onChange={e => this.onChangeAddress(e, _.get(data, 'InternalID', ''))}
                    className='address-textarea'
                    placeholder={ENDORSE_LANG.enterAddress}
                  />
                </div>
              )
            }
          </React.Fragment>)
      }
    }
    )
    return formData
  }

  render () {
    const {
      policyDetailLoading, detailsData, submitGosureLoading,
      gosureDetailsMessage, policyDetailError, aggregateDetailsData,
      submitAggregateLoading, aggregateDetailLoading
    } = this.props
    const isLoaderStart = (policyDetailLoading || aggregateDetailLoading ||
      submitGosureLoading || submitAggregateLoading
    )
    // this is used to create the array from single object check
    const policyData = detailsData && !isEmpty(detailsData) ? [detailsData] : aggregateDetailsData
    const endorseForm = this.getEndorseForms(policyData)
    this.firstInternalId = _.get(policyData, '[0].InternalID', '')
    this.totalPolicies = policyData.length
    const { isBtnDisAbled } = this.state
    const isSuccessFulEndorse = (gosureDetailsMessage === 'success') ||
      (_.get(detailsData, 'EndorsementStatus', '') === 'SUCCESS') || (policyData.length && !endorseForm.length)
    return (
      <ContainerStyle>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyDetailError ? this.showErrorMessage()
            : <CircularLoader isSpining={isLoaderStart}>
              <GosureFormContainer>
                <ContainerTitle>
                  <IntlMessages id={ENDORSE_LANG.uploadImages} />
                </ContainerTitle>
                <ContainerSubTitle>
                  <IntlMessages id={ENDORSE_LANG.subTitle} />
                </ContainerSubTitle>
                { endorseForm }
                <ButtonContainer>
                  <Button
                    type='primary'
                    disabled={isBtnDisAbled}
                    className='form-btn'
                    htmlType='submit'
                    key='submit'
                    onClick={this.submitGosureEndorseForm}
                  >
                    <IntlMessages id={LANG_STRINGS.submit} />
                  </Button>
                </ButtonContainer>
              </GosureFormContainer>
            </CircularLoader>
        }
      </ContainerStyle>
    )
  }
}

export default connect(
  state => ({
    getPolicyDetailResult: state.Policy.getPolicyDetailResult,
    policyDetailLoading: state.Loading.POLICY_DETAILS,
    aggregateDetailLoading: state.Loading.AGGREGATE_POLICY_DETAILS,
    policyDetailError: state.Error.POLICY_DETAILS,
    gosureDetailsMessage: state.Endorsement.gosureDetailsMessage,
    submitGosureLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitAggregateLoading: state.Loading.SUBMIT_AGGREGATE_ENDORSE,
    submitGosureError: state.Error.SUBMIT_GOSURE_ENDORSE,
    detailsData: state.Policy.detailsData,
    aggregateEndorseSuccess: state.Endorsement.aggregateEndorseSuccess,
    aggregateDetailsData: state.Policy.aggregateDetailsData
  }),
  {
    getPolicyDetails,
    resetGosureEndorseRedux,
    getAggregatePolicyDetails,
    submitAggregateEndorse,
    submitGosureEndorseForm
  }
)(injectIntl(GosureEndorseContainer))
