import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Row, Col } from 'antd'
import _ from 'lodash/object'
import FileUpload from '../FileUpload'
import { ENDORSE_LANG } from '../../../constants'

class FileUploadSection extends Component {
  static propTypes = {
    getUploadUrls: PropTypes.func,
    internalId: PropTypes.string
  }

  constructor (props) {
    super(props)
    this.state = {
      imageUrls: {},
      filesSections: [
        {
          tile: 'top',
          title: ENDORSE_LANG.uploadFrontImage
        },
        {
          tile: 'bottom',
          title: ENDORSE_LANG.uploadBackImage
        },
        {
          tile: 'left',
          title: ENDORSE_LANG.uploadeLeftImage
        },
        {
          tile: 'right',
          title: ENDORSE_LANG.uploadeRightImage
        }
      ]
    }
  }

  getUploadImageUrl = (url, active) => {
    this.setState((prevState) => ({
      imageUrls: {
        ...prevState.imageUrls,
        [active]: url
      }
    }), () => {
      const isAllFields = !(Object.keys(this.state.imageUrls).length < 4)
      this.props.getUploadUrls(this.state.imageUrls, isAllFields, this.props.internalId)
    })
  }

  render () {
    const { imageUrls, filesSections } = this.state
    return (
      <Row type='flex'>
        {
          filesSections.map(item => (
            <Col xs={24} sm={10} xl={5} key={item.tile}>
              <FileUpload
                active={item.tile}
                imgUrl={_.get(imageUrls, item.tile)}
                title={item.title}
                getUploadImageUrl={this.getUploadImageUrl}
              />
            </Col>
          ))
        }
      </Row>
    )
  }
}

export default FileUploadSection
