import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import _ from 'lodash/object'
import { FileUploadStyle, UploadImageTextStyle } from './index.style'
import userActions from '../../../../../redux/user/actions'
import { Upload, notification } from 'antd'
import { injectIntl } from 'react-intl'
import CircularLoader from '../../../../../components/CircularLoader'
import IntlMessages from '../../../../../components/utility/intlMessages'
import { UPLOAD_ICON } from '../../../../../constants/icons'

const { uploadUserFile, resetUserRedux } = userActions
class FileUpload extends Component {
  static propTypes = {
    active: PropTypes.string,
    imgUrl: PropTypes.string,
    title: PropTypes.string,
    getUploadImageUrl: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      activeUpload: ''
    }
  }

  componentWillReceiveProps (nextProps) {
    const { userFile, active } = nextProps

    if (_.get(userFile, 'url') && active === this.state.activeUpload) {
      this.props.getUploadImageUrl(_.get(userFile, 'url'), this.state.activeUpload)
      this.props.resetUserRedux(['userFile'])
      this.setState({
        activeUpload: ''
      })
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  customRequest = ({ file }) => {
    this.setState({
      activeUpload: this.props.active
    })
    const { type } = file
    const validImageTypes = ['image/gif', 'image/jpeg', 'image/png']
    if (validImageTypes.includes(type)) {
      const formData = new FormData()
      formData.append('file', file)
      this.props.uploadUserFile({
        body: formData
      })
    } else {
      notification.error({
        key: 'profile',
        message: this.intlText({ id: 'Salah format, harap unggah hanya gif/jpeg/png' })
      })
    }
  }

  render () {
    const { uploadFileLoading, imgUrl, active, title } = this.props
    const isUploading = !!uploadFileLoading && (this.state.activeUpload === active)
    return (
      <FileUploadStyle>
        <Upload
          name='avatar'
          listType='picture-card'
          showUploadList={false}
          multiple={false}
          disabled={isUploading}
          customRequest={this.customRequest}
        >
          {imgUrl ? (
            <CircularLoader isSpining={isUploading}>
              <img
                src={imgUrl}
                alt='avatar'
                style={{ maxHeight: '128px', maxWidth: '128px' }}
              />
            </CircularLoader>
          )
            : (
              <div className='upload-container'>
                {
                  isUploading ? <CircularLoader isSpining={isUploading} />
                    : <img src={UPLOAD_ICON} className='upload-icon' alt='icon' />
                }
                <UploadImageTextStyle>
                  <IntlMessages id={title} />
                </UploadImageTextStyle>
              </div>
            )}
        </Upload>
      </FileUploadStyle>
    )
  }
}

export default connect(
  (state) => ({
    details: state.User.details,
    userFile: state.User.userFile,
    uploadFileLoading: state.Loading.UPLOAD_USER_FILE,
    uploadFileError: state.Error.UPLOAD_USER_FILE,
    uploadUserFileMessage: state.User.uploadUserFileMessage
  }),
  {
    uploadUserFile,
    resetUserRedux
  }
)(injectIntl(FileUpload))
